local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["cf0406e3b556bc2a"] = { "Credi davvero di fare progressi? Non potrai mai sconfiggere il Flagello! Queste piccole vittorie sono solo un trucco per farti peccare di presunzione!", "." },
  ["cf0633777fc347fc"] = { "Anche se ce l'avessi, <sciocco/sciocca>, credi che te lo lascerei prendere? L'unico modo per averlo, se mai ce l'avessi, sarebbe strapparlo dalle mie fredde dita senza vita.\n\nE questo, <piccolo/piccola> <amico/amica> <mio/mia>, non succederà tanto presto.", "." },
  ["cf14ecbdbfd33df1"] = { "Hai visto? L'ultimo fuoco d'artificio ha quasi dato fuoco alla camicia di quel nano! Ah!", "." },
  ["cf1945d64b928ab8"] = { "È ora della mia ronda. Torno presto.", "." },
  ["cf1a734380d951d7"] = { "Questa terra gelata basterà, per cominciare. Venite da me, mortali, e vi darò una morte rapida e dolorosa.", "." },
  ["cf1ddc576ce8338a"] = { "%s lascia cadere l'arma.", "." },
  ["cf1e75d35242b35d"] = { "Durante le tue battaglie contro il Flagello a Naxxramas, se ti imbatti in bastioni sconsacrati e brandelli a piastre stracciati, portameli e forgerò per te un pezzo di questa armatura indossata dagli eroi.", "." },
  ["cf1f715fa65f2653"] = { "La temperatura è di 12 gradi Kraklenheit. Che emozione.", "." },
  ["cf23ad561ff1cda1"] = { "Dove si è cacciato il ragazzo stavolta?", "." },
  ["cf253d413bd15b3a"] = { "La premura che mostri per il benessere dei tuoi compagni animali è lodevole. Bulrug, sull'altura inferiore, può aiutarti. Cercalo tra la banca e la locanda.", "." },
  ["cf28f1e123353f87"] = { "Credi di avere la stoffa per estrarre minerali?", "." },
  ["cf2a01b9b3f8fc8c"] = { "Proprio così... bel vestito, Jessica.", "." },
  ["cf37e784fb3fe535"] = { "Ancora un attimo, ci sono quasi!", "." },
  ["cf3e54de752f595c"] = { "Questo è un mango? Stupendo!", "." },
  ["cf3ebe5ee6da773e"] = { "Ciao, sorella. Cos'abbiamo qui?", "." },
  ["cf4063812aa63eaa"] = { "I nani non si ubriacano, <signorino/signorina>. È solo che barcollo un pochino.\n\nComunque, Windsor? Secondo me è da qualche parte nei ⟦Blackrock Depths=Sotterranei di Roccianera⟧. È la città dei ⟦Dark Iron=Ferroscuro⟧, per voi gente ignorantata.", "." },
  ["cf42dbda5bc85551"] = { "Spero che tu sia <pronto/pronta>, {name}. Seguimi.", "." },
  ["cf50f8c4dbf167d0"] = { "{name} ha lasciato cadere la Bandiera dell'⟦Horde=Orda⟧!", "." },
  ["cf5ce97b4d8f9f0e"] = { "Ora da' un'altra lunga occhiata, prima di dirigerci verso l'Holy District e la grande ⟦Cathedral of Light=Cattedrale della Luce⟧.", "." },
  ["cf658ce11a5e1a2d"] = { "<Benvenuto/Benvenuta> alla Banca di Darnassus. Offriamo conti e cassette di sicurezza per gli oggetti di valore. Hai già un conto presso di noi, <signore/signora>?", "." },
  ["cf65df7cee487f2d"] = { "Prima uccidi, poi fai domande... Arrivano!", "." },
  ["cf6a8b321f4a79d6"] = { "Salve, Charys. Ho la mia lista: potresti procurarmi tutto, soprattutto l'ultimo ingrediente?", "." },
  ["cf6c46871e789b70"] = { "Cittadini e alleati di ⟦Stormwind=Roccavento⟧, oggi si è fatta la storia. {name} ha annientato ciò che aveva tentato di usurpare il governo del regno. Radunatevi e unitevi a me nell'onorare i nostri eroi.", "." },
  ["cf74f82c7973695d"] = { "Ora mi appartieni.", "." },
  ["cf7564b06c399eea"] = { "La tua testa sarà un bel trofeo, {race}.", "." },
  ["cf7833a2c91b3dd6"] = { "Subito, signore.", "." },
  ["cf7bc080834c55d9"] = { "L'enorme bulbo oculare sospeso al centro della sala volge lo sguardo su di te. Sei al cospetto di un dio.", "." },
  ["cf7ccb06c079c8a7"] = { "E le Spigole Screziate se ne sono andate per questa settimana! Resterò ancora un'ora per permetterti di consegnare i tuoi pesci!", "." },
  ["cf8038c2611a4ff9"] = { "Quale istruttore di professione stai cercando?", "." },
  ["cf82ada229fed3e3"] = { "Resta vicino a me, {name}. Ti proteggerò se qualcosa va storto.", "." },
  ["cf86d0390c89fa61"] = { "Voglio vedere la tua merce, Calandrath.", "." },
  ["cf8714be8b8313a1"] = { "Dunque... dunque è così che finisce, amore mio...", "." },
  ["cf989895ac6971e5"] = { "Morto? Ti ha dato di volta il cervello, {name}? Pardon, <signor/signora> {name}! Windsor non sarebbe mai morto per una cinquantina di orchi. Com'è vero che il sanguinaccio di Thelsamar è il cibo più gustoso che il mondo conoscerà mai, eccolo lì, in piedi: era coperto di pezzi d'orco dalla testa ai piedi, inzuppato in circa diciotto strati del loro sangue, ma era decisamente vivo... e molto, molto arrabbiato.", "." },
  ["cf9fcd0d8e2fa8e9"] = { "Non cadete nella trappola dei mortali. Bagnatevi nel mio potere! Rinnovatevi e distruggete gli eretici!", "." },
  ["cfa7bea85d50bf9e"] = { "Falthir, non ho più i miei ⟦Zandalar Predator's Bracers=Bracciali del Predatore degli Zandalari⟧. Puoi darmene un paio nuovo?", "." },
  ["cfab29978bbd40e5"] = { "Tra i poteri che vengono da oltre il Vuoto, la succube è uno dei più pericolosi, perché i deboli sono i più facili da avvolgere attorno alle sue dita.\n\nRicordalo, ora e in futuro.", "." },
  ["cfacb877d2e3a816"] = { "Fare ricerca a Theramore è un lavoro interessante, ma in questa città è proprio difficile trovare un letto morbido!", "." },
  ["cfb59d5c966038b4"] = { "Ok, muoviamoci!", "." },
  ["cfb61ffc8b64c85b"] = { "Guardia, porta qui il prigioniero. Mettilo nel Circle of Binding.", "." },
  ["cfb6585c27442ef9"] = { "Ben fatto, <servo/serva>. Per tanto tempo la prigione del Signore del Fuoco mi ha tenuto in catene. Ora posso di nuovo banchettare con il mondo esterno! La terra sarà di nuovo devastata dalla forza del Vento Eterno!", "." },
  ["cfb80984a967336e"] = { "Benvenuta, sorella mia. Se sei qui per addestrarti, mi farà piacere addestrarti.\n\nCorrono voci di discordia all'interno del ⟦Cenarion Circle=Circolo Cenariano⟧, ma non dovresti dare ascolto a simili chiacchiere. Il nostro sommo {class}, ⟦Fandral Staghelm=Fandral Elmocervo⟧, guida noi e tutta Teldrassil verso la gloria!", "." },
  ["cfd03f217aeb0221"] = { "Che An'she ti benedica, <figliolo/figliola>.\r\n\nAbbiamo la tradizione di spargere incenso ai venti, e mi chiedevo se ti interesserebbe onorarla.\r\n\nDovrai preparare l'incenso acquistando erbe da Nida, legno di cedro da Nata, filo di tendine da Mahu sull'altura di mezzo, e pietra focaia ed esca cerimoniali da Naal sull'altura superiore. Una volta che li avrai, combinali e spargili dalla scogliera rivolta a sud dell'Altura dei Cacciatori.\r\n\nAl luogo della cerimonia troverai una stuoia e dell'incenso.", "." },
  ["cfd0cf3494c04d6c"] = { "Lo spirito di Echeyakee scorre in te, {name}.", "." },
  ["cfd20ffde7aeeda8"] = { "Ehi, Jangdor, puoi insegnarmi di nuovo a fare un ⟦Wild Leather Cloak=Mantello di Cuoio Selvatico⟧?", "." },
  ["cfdd0e59f17d9cd3"] = { "%s indica verso ovest.", "." },
  ["cfe0b2564c9391af"] = { "Ehi, qualcuno mi aiuti a prendere questo coso!", "." },
  ["cfe0f251e2db144e"] = { "Ah, Stonebrow di questi tempi non lascia quasi mai ⟦Ironforge=Forgiardente⟧, quindi se vuoi imparare la Sartoria dovrai andare a trovarlo lassù a ⟦Ironforge=Forgiardente⟧.", "." },
  ["cfe2af137aa01b0f"] = { "Credo che l'anziano Spezzasassi sia andato a Maraudon, in ⟦Desolace=Desolanda⟧.", "." },
  ["cfeb55290a711701"] = { "Morte a qualunque {race} si metta sulla mia strada!", "." },
  ["cfedf86221f4c830"] = { "Buona fortuna, {name}. E ricorda: cerca Muiredon dopo aver portato a termine il compito.", "." },
  ["cff2e4b2869246cc"] = { "%s distrugge la picca!", "." },
  ["cff6852b997e52d9"] = { "Il potere della ⟦Tear of the Moons=Lacrima delle Lune⟧ è mio! Mio, ho detto!", "." },
  ["cffd875bf424fbf8"] = { "Cra cra.", "." },
})
